import {expect} from '@playwright/test';

export async function exerciseComposition(page,info,lang){
  const text=(zh,en)=>lang==='en'?en:zh,panel=page.locator('.composition-panel'),canvas=page.locator('.composition-canvas'),handle=name=>canvas.locator(`[data-crop-handle="${name}"]`),width=page.getByRole('slider',{name:'Crop width',exact:true}),undo=page.getByRole('button',{name:text('撤销编辑','Undo edit'),exact:true}),redo=page.getByRole('button',{name:text('重做编辑','Redo edit'),exact:true});
  await panel.locator('summary').click();await panel.locator('.interactive-crop-trigger').click();await expect(handle('se')).toBeEnabled();await expect(canvas.locator('[data-crop-handle]')).toHaveCount(8);await expect(canvas.locator('.composition-thirds line')).toHaveCount(4);await expect(undo).toBeDisabled();
  await canvas.scrollIntoViewIfNeeded();const box=await handle('se').boundingBox();await page.mouse.move(box.x+box.width/2,box.y+box.height/2);await page.mouse.down();await page.mouse.move(box.x+box.width/2-60,box.y+box.height/2-30,{steps:8});await expect(undo).toBeDisabled();await page.mouse.up();const resized=Number(await width.inputValue());expect(resized).toBeLessThan(100);await expect(undo).toBeEnabled();await undo.click();await expect(width).toHaveValue('100');await expect(undo).toBeDisabled();await redo.click();expect(Number(await width.inputValue())).toBe(resized);
  if(page.viewportSize().width===390){
    await canvas.scrollIntoViewIfNeeded();const b=await handle('se').boundingBox(),x=b.x+b.width/2,y=b.y+b.height/2,session=await page.context().newCDPSession(page);
    try{await session.send('Emulation.setTouchEmulationEnabled',{enabled:true,maxTouchPoints:1});await session.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x,y}]});await session.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[{x:x-12,y:y-10}]});await session.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});}finally{await session.send('Emulation.setTouchEmulationEnabled',{enabled:false});await session.detach();}
    expect(Number(await width.inputValue())).toBeLessThan(resized);await undo.click();expect(Number(await width.inputValue())).toBe(resized);
  }
  const ratios=panel.getByRole('combobox',{name:text('裁剪比例','Crop ratio'),exact:true});await ratios.selectOption('2.35');expect(Number(await canvas.locator('[data-crop-body]').getAttribute('width'))/Number(await canvas.locator('[data-crop-body]').getAttribute('height'))).toBeCloseTo(2.35,5);await ratios.selectOption('1.5');
  const cropZoom=panel.getByRole('slider',{name:text('取景缩放','Crop zoom'),exact:true});await cropZoom.scrollIntoViewIfNeeded();const z=await cropZoom.boundingBox(),beforeZoom=Number(await canvas.locator('[data-crop-body]').getAttribute('width'));await page.mouse.move(z.x+8,z.y+z.height/2);await page.mouse.down();await page.mouse.move(z.x+z.width*.8,z.y+z.height/2,{steps:8});expect(Number(await cropZoom.inputValue())).toBeGreaterThan(10);expect(Number(await canvas.locator('[data-crop-body]').getAttribute('width'))).toBeLessThan(beforeZoom/10);await page.mouse.move(z.x-20,z.y+z.height/2,{steps:8});await page.mouse.up();expect(Number(await cropZoom.inputValue())).toBeCloseTo(1,4);expect(Number(await canvas.locator('[data-crop-body]').getAttribute('width'))).toBeCloseTo(beforeZoom,5);await cropZoom.focus();await page.keyboard.press('ArrowRight');expect(Number(await cropZoom.inputValue())).toBeCloseTo(1.01,5);await undo.click();expect(Number(await canvas.locator('[data-crop-body]').getAttribute('width'))).toBeCloseTo(beforeZoom,5);
  const ruler=panel.getByRole('slider',{name:text('校正角度','Straighten angle'),exact:true});await ruler.scrollIntoViewIfNeeded();const range=await ruler.boundingBox();await page.mouse.move(range.x+range.width/2,range.y+range.height/2);await page.mouse.down();await page.evaluate(async()=>{await new Promise(requestAnimationFrame);await new Promise(requestAnimationFrame)});const startAngle=Number(await ruler.inputValue()),originalWidth=Number(await canvas.locator('[data-crop-body]').getAttribute('width'));await page.mouse.move(range.x+range.width*.82,range.y+range.height/2,{steps:8});await page.mouse.move(range.x+range.width/2,range.y+range.height/2,{steps:8});await page.mouse.up();expect(Number(await ruler.inputValue())).toBeCloseTo(startAngle,4);expect(Number(await canvas.locator('[data-crop-body]').getAttribute('width'))).toBeCloseTo(originalWidth,5);
  await page.mouse.click(range.x+range.width*.68,range.y+range.height/2);const first=Number(await ruler.inputValue());expect(first).toBeGreaterThan(5);expect(first).toBeLessThan(35);await ruler.focus();await page.keyboard.press('ArrowRight');expect(Number(await ruler.inputValue())).toBeCloseTo(first+.1,5);
  await canvas.scrollIntoViewIfNeeded();const body=canvas.locator('[data-crop-body]'),geometry=await body.evaluate(el=>{const m=el.getScreenCTM();return {width:Number(el.getAttribute('width')),height:Number(el.getAttribute('height')),scaleX:m.a,scaleY:m.d};});expect(geometry.width/geometry.height).toBeCloseTo(1.5,4);expect(geometry.scaleX).toBeCloseTo(geometry.scaleY,8);const x=Number(await body.getAttribute('x'));await body.focus();await page.keyboard.press('ArrowRight');expect(Number(await body.getAttribute('x'))).toBeGreaterThan(x);
  const before=await width.inputValue(),cancelBox=await handle('nw').boundingBox();await page.mouse.move(cancelBox.x+cancelBox.width/2,cancelBox.y+cancelBox.height/2);await page.mouse.down();await page.mouse.move(cancelBox.x+cancelBox.width/2+20,cancelBox.y+cancelBox.height/2+20,{steps:4});await expect(undo).toBeDisabled();await page.keyboard.press('Escape');await page.mouse.up();await expect(width).toHaveValue(before);
  await panel.getByRole('button',{name:text('左转 90°','Rotate left 90°'),exact:true}).click();await expect(handle('se')).toBeEnabled();await panel.getByRole('button',{name:'90°',exact:true}).click();await expect(handle('se')).toBeEnabled();await panel.getByRole('button',{name:text('水平翻转','Flip horizontal'),exact:true}).click();await expect(handle('se')).toBeEnabled();await panel.getByRole('button',{name:'90°',exact:true}).click();await expect(handle('se')).toBeEnabled();await canvas.scrollIntoViewIfNeeded();
  const expected={width:Math.max(1,Math.round(Number(await body.getAttribute('width')))),height:Math.max(1,Math.round(Number(await body.getAttribute('height')))),angle:Number(await ruler.inputValue())};expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);if(lang==='en')expect(await panel.innerText()).not.toMatch(/[\u3400-\u9fff]/);await canvas.screenshot({path:info.outputPath('interactive-composition.png')});
  await canvas.getByRole('button',{name:text('完成裁剪','Done cropping'),exact:true}).click();await expect(panel.locator('.interactive-crop-trigger')).toBeFocused();await expect(page.locator('.edit-image img')).toHaveJSProperty('naturalWidth',expected.width);await expect(page.locator('.edit-image img')).toHaveJSProperty('naturalHeight',expected.height);
  expected.digest=await page.locator('.edit-image img').evaluate(async img=>{const canvas=new OffscreenCanvas(img.naturalWidth,img.naturalHeight),context=canvas.getContext('2d');context.drawImage(img,0,0);return [...new Uint8Array(await crypto.subtle.digest('SHA-256',context.getImageData(0,0,canvas.width,canvas.height).data))].join(',');});return expected;
}

export async function pngPixelsDigest(page,bytes){return page.evaluate(async base64=>{const data=Uint8Array.from(atob(base64),c=>c.charCodeAt(0)),image=await createImageBitmap(new Blob([data],{type:'image/png'})),canvas=new OffscreenCanvas(image.width,image.height),context=canvas.getContext('2d');context.drawImage(image,0,0);image.close();return [...new Uint8Array(await crypto.subtle.digest('SHA-256',context.getImageData(0,0,canvas.width,canvas.height).data))].join(',');},bytes.toString('base64'));}
